# DISCLAMER: This file is generated by AI for testing purposes.
import logging
import unittest

from iSpy.iSpy import iSpy


class FakeCamera:
    def __init__(self, name, frame_processors=None):
        self._camera_config = {"name": name}
        if frame_processors is not None:
            self._camera_config["frame_processors"] = frame_processors
        self.attached = []

    def add_frame_processor(self, processor):
        self.attached.append(processor)


class FrameProcessorAssignmentTests(unittest.TestCase):
    def _vision(self, cameras, names=("a", "b")):
        vision = iSpy.__new__(iSpy)
        vision.logger = logging.getLogger("test.frame_processors")
        vision.frame_processors = {name: object() for name in names}
        vision.cameras = cameras
        return vision

    def test_absent_list_keeps_global_for_all_behavior(self):
        camera = FakeCamera("cam")
        vision = self._vision([camera])
        vision._attach_frame_processors()
        self.assertEqual(camera.attached, list(vision.frame_processors.values()))

    def test_per_camera_list_uses_only_named_processors_in_order(self):
        camera = FakeCamera("cam", ["b", "a"])
        vision = self._vision([camera])
        vision._attach_frame_processors()
        self.assertEqual(
            camera.attached,
            [vision.frame_processors["b"], vision.frame_processors["a"]],
        )

    def test_empty_list_disables_processing_for_that_camera_only(self):
        off = FakeCamera("off", [])
        on = FakeCamera("on", ["a"])
        vision = self._vision([off, on])
        vision._attach_frame_processors()
        self.assertEqual(off.attached, [])
        self.assertEqual(on.attached, [vision.frame_processors["a"]])

    def test_unknown_name_is_skipped_without_breaking_other_processors(self):
        camera = FakeCamera("cam", ["missing", "a"])
        vision = self._vision([camera])
        with self.assertLogs("test.frame_processors", level="WARNING") as logs:
            vision._attach_frame_processors()
        self.assertEqual(camera.attached, [vision.frame_processors["a"]])
        self.assertIn("missing", "\n".join(logs.output))


if __name__ == "__main__":
    unittest.main()
